package dev.xantha.vss.client.prediction;

import net.minecraft.util.Mth;
import net.minecraft.world.level.levelgen.DensityFunction;

/** Typed calls are remapped by the loader's build, unlike names embedded in generated bytecode. */
final class DensityCompilerSupport {
    static double compute(DensityFunction function, DensityFunction.FunctionContext context) {
        return function.compute(context);
    }

    static double gradient(DensityFunction.FunctionContext context, double fromY, double toY,
                           double fromValue, double toValue) {
        return Mth.clampedMap(context.blockY(), fromY, toY, fromValue, toValue);
    }

    static double clamp(double value, double min, double max) {
        return Mth.clamp(value, min, max);
    }

    static double minValue(DensityFunction function) { return function.minValue(); }
    static double maxValue(DensityFunction function) { return function.maxValue(); }

    private DensityCompilerSupport() { }
}
